import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] a = new int[n];
        int[] b = new int[m];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        for (int i = 0; i < m; i++) b[i] = sc.nextInt();
        Arrays.sort(a);
        Arrays.sort(b);

        PriorityQueue<Integer> pq = new PriorityQueue<>();
        int j = 0;
        long ans = 0;

        for (int i = 0; i < n; i++) {
            while (j < m && b[j] <= a[i]) {
                pq.offer(b[j]);
                j++;
            }
            if (!pq.isEmpty()) {
                pq.poll();
                ans += a[i];
            }
        }

        System.out.println(j == m ? ans : -1);
    }
}
